def compute(vars):
    old = vars["v1"]
    new = vars["v2"]

    if old == 0:
        return None

    change_ratio = (new - old) / old
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old": old,
            "new": new,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
